export type TranslationKey = keyof typeof messages["zh-CN"];

interface LocaleContextValue {
  locale: AppLocale;
  setLocale: (locale: AppLocale) => void;
  t: (key: TranslationKey | string) => string;
  tr: (source: string) => string;
}

