function translateLegacy(locale: AppLocale, source: string) {
  if (locale === "zh-CN" || !source) return source;
  const dictionary = legacyMessages[locale];
  if (dictionary[source]) return dictionary[source];

  const entries = Object.entries(dictionary).sort(([left], [right]) => right.length - left.length);
  const translated = entries.reduce((value, [from, to]) => value.replaceAll(from, to), source);
  return /[\u3400-\u9fff]/.test(translated) ? (locale === "en-US" ? "Localized content" : "Konten terlokalkan") : translated;
}

function LegacyContentTranslator({ locale }: { locale: AppLocale }) {
  const textSources = useRef(new WeakMap<Text, { source: string; rendered: string }>());
  const attributeSources = useRef(new WeakMap<Element, Map<string, { source: string; rendered: string }>>());

  useEffect(() => {
    const attributes = ["aria-label", "placeholder", "title"];
    let applying = false;

    const translateNode = (node: Node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        const text = node as Text;
        const parent = text.parentElement;
        if (!parent || parent.closest("[data-locale-static='false']") || ["SCRIPT", "STYLE", "TEXTAREA", "OPTION"].includes(parent.tagName)) return;
        const current = text.nodeValue ?? "";
        const previous = textSources.current.get(text);
        const source = !previous || current !== previous.rendered ? current : previous.source;
        const translated = translateLegacy(locale, source);
        textSources.current.set(text, { source, rendered: translated });
        if (translated !== current) text.nodeValue = translated;
        return;
      }
      if (node.nodeType !== Node.ELEMENT_NODE) return;
      const element = node as Element;
      if (element.closest("[data-locale-static='false']") || ["SCRIPT", "STYLE", "TEXTAREA", "OPTION"].includes(element.tagName)) return;
      for (const attribute of attributes) {
        const current = element.getAttribute(attribute);
        if (!current) continue;
        const sourceMap = attributeSources.current.get(element) ?? new Map<string, { source: string; rendered: string }>();
        const previous = sourceMap.get(attribute);
        const source = !previous || current !== previous.rendered ? current : previous.source;
        const translated = translateLegacy(locale, source);
        sourceMap.set(attribute, { source, rendered: translated });
        attributeSources.current.set(element, sourceMap);
        if (translated !== current) element.setAttribute(attribute, translated);
      }
      element.childNodes.forEach(translateNode);
    };

    const root = document.body;
    applying = true;
    translateNode(root);
    applying = false;
    const observer = new MutationObserver((mutations) => {
      if (applying) return;
      applying = true;
      mutations.forEach((mutation) => {
        if (mutation.type === "characterData") translateNode(mutation.target);
        mutation.addedNodes.forEach(translateNode);
        if (mutation.type === "attributes") translateNode(mutation.target);
      });
      applying = false;
    });
    observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: attributes });
    return () => observer.disconnect();
  }, [locale]);

  return null;
}

