const LocaleContext = createContext<LocaleContextValue | null>(null);

function getInitialLocale(): AppLocale {
  if (typeof window === "undefined") {
    return "zh-CN";
  }

  const savedLocale = window.localStorage.getItem(STORAGE_KEY);
  if (SUPPORTED_LOCALES.includes(savedLocale as AppLocale)) {
    return savedLocale as AppLocale;
  }

  const browserLocale = window.navigator.language.toLowerCase();
  if (browserLocale.startsWith("en")) return "en-US";
  return "zh-CN";
}

function antdLocaleFor(locale: AppLocale) {
  if (locale === "en-US") return enUS;
  if (locale === "id-ID") return idID;
  return zhCN;
}

export function AppLocaleProvider({ children }: PropsWithChildren) {
  const [locale, setLocale] = useState<AppLocale>("zh-CN");
  const [localeReady, setLocaleReady] = useState(false);

  useEffect(() => {
    setLocale(getInitialLocale());
    setLocaleReady(true);
  }, []);

  useEffect(() => {
    if (!localeReady) return;
    window.localStorage.setItem(STORAGE_KEY, locale);
    document.documentElement.lang = locale;
  }, [locale, localeReady]);

  const value = useMemo<LocaleContextValue>(
    () => ({
      locale,
      setLocale,
      t: (key) => messages[locale][key as TranslationKey] ?? translateLegacy(locale, key),
      tr: (source) => translateLegacy(locale, source),
    }),
    [locale],
  );

  return (
    <LocaleContext.Provider value={value}>
      <ConfigProvider theme={modernTheme} locale={antdLocaleFor(locale)}>
        {children}
        <LegacyContentTranslator locale={locale} />
      </ConfigProvider>
    </LocaleContext.Provider>
  );
}

export function useLocale() {
  const context = useContext(LocaleContext);
  if (!context) {
    throw new Error("useLocale must be used within AppLocaleProvider");
  }
  return context;
}
